import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.C1fFCwpm.js";const p=JSON.parse('{"title":"BooLua (modded build)","description":"","frontmatter":{},"headers":[],"relativePath":"boolua/index.md","filePath":"boolua/index.md","lastUpdated":1793848638000}'),d={name:"boolua/index.md"};function r(l,e,i,c,n,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="boolua-modded-build" tabindex="-1">BooLua (modded build) <a class="header-anchor" href="#boolua-modded-build" aria-label="Permalink to &quot;BooLua (modded build)&quot;">​</a></h1><p><strong>BooLua</strong> is the <strong>mydll-patched</strong> CreativeGrowtopia V1.50 build. It exposes the <strong>entire <a href="/CGT_Docs_API/api/globals">native V1.50 API</a></strong> <em>plus</em> the extra functions on this page, and changes the behaviour of a few native ones (see <a href="/CGT_Docs_API/boolua/overrides">Overrides</a>).</p><div class="tip custom-block"><p class="custom-block-title">Two builds, one site</p><p>Use the <strong>Native (Ori)</strong> section for the stock V1.50 API dumped from <code>_G</code>. Use <strong>BooLua</strong> here for everything the loader adds or changes. Everything in Native also works in BooLua.</p></div><h2 id="what-boolua-adds" tabindex="-1">What BooLua adds <a class="header-anchor" href="#what-boolua-adds" aria-label="Permalink to &quot;What BooLua adds&quot;">​</a></h2><ul><li><p><strong><a href="/CGT_Docs_API/boolua/functions">Added functions</a></strong> - fly, anti-portal, mod-zoom, no-lock tiles, version/protocol bypass, and an HTTP <code>MakeRequest</code>.</p></li><li><p><strong><a href="/CGT_Docs_API/boolua/overrides">Overrides</a></strong> - native behaviour the patch changes (<code>GetTile.extra</code>, <code>MakeRequest</code>), plus the <code>io</code>/<code>os</code> sandbox.</p></li><li><p><strong><a href="/CGT_Docs_API/boolua/examples">Examples</a></strong> - ready-to-adapt scripts (fly, anti-portal, version bypass, fast tile scan, webhook).</p></li></ul><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><p>Each function&#39;s badge shows where it exists. Android ships the full set; the PC <code>mydll.dll</code> ships the core (<code>_SetFly</code>, <code>_FlyState</code>, <code>ChangeValue</code>, <code>MakeRequest</code>, anti-portal) plus PC-only RE/debug helpers: <code>_DumpObjects</code>, <code>_ScanObjects</code>, <code>_ScanDrops</code>, <code>_ScanCandidates</code>, <code>_ScanTiles</code>, <code>_FindFloat</code>, <code>_RefineFloat</code>.</p><div class="warning custom-block"><p class="custom-block-title">Unofficial &amp; loader-specific</p><p>These come from the <strong>mydll loader source</strong>, not the game binary. Names and behaviour depend on your loader version.</p></div>',8)])])}const m=o(d,[["render",r]]);export{p as __pageData,m as default};
